fn longueur(s: String) -> usize {
    s.len()
}

fn main() {
    let s = String::from("héron");
    let n = longueur(s.clone());
    println!("{n} {s}");
}

fn afficher(v: Vec<i32>) {
    println!("{v:?}");
}

fn main() {
    let v = vec![1, 2, 3];
    afficher(v);
    println!("{}", v.len());
}

